package com.circlenet.domain.person;
import com.circlenet.domain.circle.CircleMediaStorage;import com.circlenet.domain.person.model.*;import com.circlenet.domain.profile.UserProfileRepository;import com.circlenet.domain.profile.ProfileMediaStorage;import com.circlenet.domain.profile.model.UserProfileEntity;import com.circlenet.domain.relationship.RelationshipRepository;import com.circlenet.domain.user.UserRepository;import java.time.Instant;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class PersonProfileService {
 private final UserRepository users;private final UserProfileRepository profiles;private final RelationshipRepository relationships;private final PersonRecordRepository records;private final PersonMemoryRepository memories;private final CircleMediaStorage media;private final ProfileMediaStorage profileMedia;
 public PersonProfileService(UserRepository u,UserProfileRepository p,RelationshipRepository r,PersonRecordRepository pr,PersonMemoryRepository m,CircleMediaStorage s,ProfileMediaStorage pm){users=u;profiles=p;relationships=r;records=pr;memories=m;media=s;profileMedia=pm;}
 @Transactional(readOnly=true) public PersonDtos.Profile get(Long owner,Long personId){var user=user(personId);var profile=profiles.findById(personId).orElse(null);boolean canEdit=canEdit(owner,user);var record=canEdit?records.findById(new PersonRecordEntity.Key(owner,personId)).orElse(null):null;var list=canEdit?memories.findByOwnerUserIdAndPersonUserIdOrderByCreatedAtDesc(owner,personId).stream().map(this::memory).toList():java.util.List.<PersonDtos.Memory>of();String display=((user.getFirstName()==null?"":user.getFirstName())+" "+(user.getSurname()==null?"":user.getSurname())).trim();if(display.isBlank())display=user.getUsername();String ownBirth="MANAGED".equals(user.getIdentityType())?user.getManagedDateOfBirth():profile==null?null:profile.getDateOfBirth();String birth=ownBirth!=null?ownBirth:record==null?null:record.getDateOfBirth();String death=user.getManagedDateOfDeath()!=null?user.getManagedDateOfDeath():record==null?null:record.getDateOfDeath();return new PersonDtos.Profile(user.getId(),display,profile==null?null:profile.getProfilePhoto(),user.getLocation(),profile==null?null:profile.getGender(),profile==null?null:profile.getBio(),profile==null?null:profile.getEmployer(),profile==null?null:profile.getJobTitle(),profile==null?null:profile.getInstitution(),user.getManagedCategory(),birth,death,user.getManagedNotes(),owner.equals(user.getGuardianUserId()),dto(record),list);}
 public PersonDtos.Profile save(Long owner,Long personId,PersonDtos.Record value){assertEditable(owner,personId);var key=new PersonRecordEntity.Key(owner,personId);var entity=records.findById(key).orElseGet(()->{var x=new PersonRecordEntity();x.setOwnerUserId(owner);x.setPersonUserId(personId);return x;});entity.setNickname(clean(value.nickname()));entity.setContactPhone(clean(value.contactPhone()));entity.setContactEmail(clean(value.contactEmail()));entity.setAddress(clean(value.address()));entity.setCity(clean(value.city()));entity.setCountry(clean(value.country()));entity.setOccupation(clean(value.occupation()));entity.setDateOfBirth(cleanDate(value.dateOfBirth()));entity.setMarriageDate(cleanDate(value.marriageDate()));entity.setDateOfDeath(cleanDate(value.dateOfDeath()));entity.setImportantDates(clean(value.importantDates()));entity.setNotes(clean(value.notes()));entity.setUpdatedAt(Instant.now());records.save(entity);relationships.findByOwnerUserIdAndRelatedUserId(owner,personId).ifPresent(relation->{relation.setRelatedBirthDate(entity.getDateOfBirth());relation.setMilestoneDate(entity.getMarriageDate());relation.setRelatedDeathDate(entity.getDateOfDeath());relationships.save(relation);});return get(owner,personId);}
 public PersonDtos.Memory addMemory(Long owner,Long personId,String title,String note,MultipartFile file){assertEditable(owner,personId);String cleanTitle=clean(title),cleanNote=clean(note);if(cleanTitle==null&&cleanNote==null&&(file==null||file.isEmpty()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Add text or choose a file");var entity=new PersonMemoryEntity();entity.setOwnerUserId(owner);entity.setPersonUserId(personId);entity.setTitle(cleanTitle);entity.setNote(cleanNote);if(file!=null&&!file.isEmpty()){var stored=media.store(owner,file);entity.setMediaKey(stored.key());entity.setMediaName(stored.name());entity.setMediaType(stored.type());entity.setMediaSize(stored.size());}return memory(memories.save(entity));}
 public PersonDtos.Profile uploadProfilePhoto(Long owner,Long personId,MultipartFile file){var person=user(personId);if(!owner.equals(personId)&&!owner.equals(person.getGuardianUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only this user or their guardian can change the profile photo");var profile=profiles.findById(personId).orElseGet(()->{var p=new UserProfileEntity();p.setUserId(personId);return p;});profileMedia.delete(profile.getProfilePhoto());profile.setProfilePhoto(profileMedia.store(owner,file));profiles.save(profile);return get(owner,personId);}
 public void deleteMemory(Long owner,Long personId,Long id){var item=memories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Memory not found"));if(!owner.equals(item.getOwnerUserId())||!personId.equals(item.getPersonUserId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Memory not found");media.delete(item.getMediaKey());memories.delete(item);}
 @Transactional(readOnly=true) public Attachment attachment(Long owner,Long personId,Long id){assertEditable(owner,personId);var item=memories.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Memory not found"));if(!owner.equals(item.getOwnerUserId())||!personId.equals(item.getPersonUserId())||item.getMediaKey()==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Attachment not found");return new Attachment(media.load(item.getMediaKey()),item.getMediaName(),item.getMediaType());}
 private boolean canEdit(Long owner,com.circlenet.domain.user.model.UserEntity person){return owner.equals(person.getId())||owner.equals(person.getGuardianUserId())||relationships.findByOwnerUserIdAndRelatedUserId(owner,person.getId()).isPresent();}private void assertEditable(Long o,Long p){if(!canEdit(o,user(p)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Add this person to your relationships before keeping private details or memories");}private com.circlenet.domain.user.model.UserEntity user(Long id){return users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Person not found"));}private String clean(String v){return v==null||v.isBlank()?null:v.trim();}private String cleanDate(String v){if(v==null||v.isBlank())return null;try{return java.time.LocalDate.parse(v.trim()).toString();}catch(java.time.format.DateTimeParseException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter a valid date");}}private PersonDtos.Record dto(PersonRecordEntity x){return x==null?new PersonDtos.Record(null,null,null,null,null,null,null,null,null,null,null,null):new PersonDtos.Record(x.getNickname(),x.getContactPhone(),x.getContactEmail(),x.getAddress(),x.getCity(),x.getCountry(),x.getOccupation(),x.getDateOfBirth(),x.getMarriageDate(),x.getDateOfDeath(),x.getImportantDates(),x.getNotes());}private PersonDtos.Memory memory(PersonMemoryEntity x){return new PersonDtos.Memory(x.getId(),x.getTitle(),x.getNote(),x.getMediaKey()==null?null:"/api/people/"+x.getPersonUserId()+"/memories/"+x.getId()+"/media",x.getMediaName(),x.getMediaType(),x.getMediaSize(),x.getCreatedAt());}public record Attachment(Resource resource,String name,String type){}
}
